// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract InvMutTest is Test {
    airDrop c;
    function setUp() public { c = new airDrop(); }
    function testRegression_property() public {
        Token token = new Token();
        address from = address(0x123);
        address[] memory tos = new address[](1);
        tos[0] = address(0x456);
        c.transfer(from, address(token), tos, 1, 1);
        assertTrue(token.balances(address(0x456)) == 10);
    }
}

contract Token {
    mapping(address => uint) public balances;
    function transferFrom(address, address to, uint value) external returns (bool) {
        balances[to] = value;
        return true;
    }
}
